/**
 * Unit tests for BasicSerializerFactory#buildIndexedListSerializer.
 */
public class BasicSerializerFactory_buildIndexedListSerializer_TriageGen0Test {

    private BasicSerializerFactory factory;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        // BasicSerializerFactory constructor is protected, so we instantiate it via a mock or a concrete implementation.
        // Since it's an abstract class in Jackson, we use a mock or a subclass.
        // However, for testing a public method of the base class, we can use Mockito to spy or create a minimal implementation.
        factory = new BasicSerializerFactory(new SerializerFactoryConfig()) {
            @Override
            public SerializerFactory withConfig(SerializerFactoryConfig config) {
                return this;
            }

            @Override
            protected Iterable<Serializers> customSerializers() {
                return null;
            }
        };
        typeFactory = TypeFactory.defaultInstance();
    }

    @Test
    public void testBuildIndexedListSerializer_Success() {
        // Arrange
        JavaType elemType = typeFactory.constructType(String.class);
        boolean staticTyping = true;
        TypeSerializer vts = mock(TypeSerializer.class);
        JsonSerializer<Object> valueSerializer = new StdSerializer<Object>(Object.class) {
            @Override
            public void serialize(Object value, com.fasterxml.jackson.core.JsonGenerator gen, com.fasterxml.jackson.databind.SerializerProvider serializers) throws java.io.IOException {
                // No-op
            }
        };

        // Act
        ContainerSerializer<?> result = factory.buildIndexedListSerializer(elemType, staticTyping, vts, valueSerializer);

        // Assert
        assertNotNull("The returned serializer should not be null", result);
        assertTrue("The returned serializer should be an instance of IndexedListSerializer", result instanceof IndexedListSerializer);

        // Since IndexedListSerializer fields are likely private, we verify the behavior via the returned type.
        // The method is a simple factory method that returns a new instance.
    }

    @Test
    public void testBuildIndexedListSerializer_DifferentParameters() {
        // Arrange
        JavaType elemType = typeFactory.constructType(Integer.class);
        boolean staticTyping = false;
        TypeSerializer vts = mock(TypeSerializer.class);
        JsonSerializer<Object> valueSerializer = mock(JsonSerializer.class);

        // Act
        ContainerSerializer<?> result = factory.buildIndexedListSerializer(elemType, staticTyping, vts, valueSerializer);

        // Assert
        assertNotNull(result);
        assertTrue(result instanceof IndexedListSerializer);
    }

    @Test
    public void testBuildIndexedListSerializer_NullParameters() {
        // Testing how the constructor of IndexedListSerializer handles nulls 
        // (Assuming it might throw NullPointerException if the internal implementation doesn't permit nulls)

        // Note: If IndexedListSerializer is designed to allow nulls, this test ensures no crash.
        // If it's designed to fail fast, we'd use @Test(expected = NullPointerException.class).

        try {
            factory.buildIndexedListSerializer(null, true, null, null);
        } catch (NullPointerException e) {
            // If the implementation throws NPE, this is a valid branch coverage for the constructor call
        } catch (Exception e) {
            // Other exceptions
        }
    }
}
